theorem List.getElem?_zipWith'.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {l₁ : List α}
  {l₂ : List β} {f : α → β → γ} {i : ℕ} :
  (List.zipWith f l₁ l₂)[i]? = (Option.map f l₁[i]?).bind fun g => Option.map g l₂[i]?

theorem List.tail_zipWithAll.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {as : List α}
  {bs : List β} {f : Option α → Option β → γ} :
  (List.zipWithAll f as bs).tail = List.zipWithAll f as.tail bs.tail

theorem List.zipWithAll_map_left.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {α' : Type u_1}
  {γ : Type u_3} {l₁ : List α} {l₂ : List β} {f : α → α'} {g : Option α' → Option β → γ} :
  List.zipWithAll g (List.map f l₁) l₂ = List.zipWithAll (fun a b => g (f <$> a) b) l₁ l₂

theorem List.zipWith_append.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {f : α → β → γ}
  {l₁ l₁' : List α} {l₂ l₂' : List β} (h : l₁.length = l₂.length) :
  List.zipWith f (l₁ ++ l₁') (l₂ ++ l₂') = List.zipWith f l₁ l₂ ++ List.zipWith f l₁' l₂'

theorem List.zipWith_map_right.{u_1, u_2, u_3, u_4} {α : Type u_1} {β : Type u_2} {β' : Type u_3}
  {γ : Type u_4} {l₁ : List α} {l₂ : List β} {f : β → β'} {g : α → β' → γ} :
  List.zipWith g l₁ (List.map f l₂) = List.zipWith (fun a b => g a (f b)) l₁ l₂

theorem List.getElem?_zipWith_eq_some.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3}
  {f : α → β → γ} {l₁ : List α} {l₂ : List β} {z : γ} {i : ℕ} :
  (List.zipWith f l₁ l₂)[i]? = some z ↔ ∃ x y, l₁[i]? = some x ∧ l₂[i]? = some y ∧ f x y = z

theorem List.zipWith_map.{u_1, u_2, u_3, u_4, u_5} {γ : Type u_1} {δ : Type u_2} {α : Type u_3}
  {β : Type u_4} {μ : Type u_5} {f : γ → δ → μ} {g : α → γ} {h : β → δ} {l₁ : List α}
  {l₂ : List β} :
  List.zipWith f (List.map g l₁) (List.map h l₂) = List.zipWith (fun a b => f (g a) (h b)) l₁ l₂

theorem List.zipWithAll_map_right.{u_1, u_2, u_3} {α : Type u_1} {β β' : Type u_2} {γ : Type u_3}
  {l₁ : List α} {l₂ : List β} {f : β → β'} {g : Option α → Option β' → γ} :
  List.zipWithAll g l₁ (List.map f l₂) = List.zipWithAll (fun a b => g a (f <$> b)) l₁ l₂

theorem List.zipWith_foldr_eq_zip_foldr.{u_1, u_2, u_3, u_4} {α : Type u_1} {β : Type u_2} {γ : Type u_3}
  {δ : Type u_4} {l₁ : List α} {l₂ : List β} {f : α → β → γ} {i : δ} {g : γ → δ → δ} :
  List.foldr g i (List.zipWith f l₁ l₂) = List.foldr (fun p r => g (f p.1 p.2) r) i (l₁.zip l₂)

theorem List.zipWith_map_left.{u_1, u_2, u_3, u_4} {α : Type u_1} {β : Type u_2} {α' : Type u_3}
  {γ : Type u_4} {l₁ : List α} {l₂ : List β} {f : α → α'} {g : α' → β → γ} :
  List.zipWith g (List.map f l₁) l₂ = List.zipWith (fun a b => g (f a) b) l₁ l₂

theorem List.head_zipWithAll.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {as : List α}
  {bs : List β} {f : Option α → Option β → γ} (h : List.zipWithAll f as bs ≠ []) :
  (List.zipWithAll f as bs).head h = f as.head? bs.head?

theorem List.head_zipWith.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {as : List α}
  {bs : List β} {f : α → β → γ} (h : List.zipWith f as bs ≠ []) :
  (List.zipWith f as bs).head h = f (as.head ⋯) (bs.head ⋯)

def List.range'.match_1.splitter✝.{u_1} (motive : ℕ → ℕ → ℕ → Sort u_1) (x✝ x✝¹ x✝² : ℕ)
  (h_1 : (x x_1 : ℕ) → motive x 0 x_1) (h_2 : (s n step : ℕ) → motive s n.succ step) :
  motive x✝ x✝¹ x✝²

theorem List.lookup_replicate_of_pos.{u_1, u_2} {α : Type u_2} [BEq α] {n : ℕ} {a : α} {α✝ : Type u_1}
  {b : α✝} {k : α} (h : 0 < n) :
  List.lookup k (List.replicate n (a, b)) = if (k == a) = true then some b else none

theorem List.Sublist.findSome?_isSome.{u_1, u_2} {α : Type u_1} {α✝ : Type u_2} {f : α → Option α✝}
  {l₁ l₂ : List α} (h : l₁.Sublist l₂) :
  (List.findSome? f l₁).isSome = true → (List.findSome? f l₂).isSome = true

def List.findIdx.go.match_1.splitter✝.{u_1, u_2} {α : Type u_1} (motive : List α → ℕ → Sort u_2)
  (x✝ : List α) (x✝¹ : ℕ) (h_1 : (n : ℕ) → motive [] n)
  (h_2 : (a : α) → (l : List α) → (n : ℕ) → motive (a :: l) n) : motive x✝ x✝¹

theorem List.findIdx?_go_eq_map_findFinIdx?_go_val.{u_1} {α : Type u_1} {l xs : List α} {p : α → Bool}
  {i : ℕ} {h : xs.length + i = l.length} :
  List.findIdx?.go p xs i = Option.map (fun x => ↑x) (List.findFinIdx?.go p l xs i h)

theorem List.findIdx_eq_getD_bind_find?_idxOf?.{u_1} {α : Type u_1} [BEq α] [LawfulBEq α] {xs : List α}
  {p : α → Bool} :
  List.findIdx p xs = ((List.find? p xs).bind fun a => List.idxOf? a xs).getD xs.length

theorem List.Sublist.lookup_isSome.{u_1, u_2} {α : Type u_2} [BEq α] {β : Type u_1} {k : α}
  {l₁ l₂ : List (α × β)} (h : l₁.Sublist l₂) :
  (List.lookup k l₁).isSome = true → (List.lookup k l₂).isSome = true

theorem List.find?_flatMap_eq_none_iff.{u_1, u_2} {α : Type u_1} {β : Type u_2} {xs : List α}
  {f : α → List β} {p : β → Bool} :
  List.find? p (List.flatMap f xs) = none ↔ ∀ x ∈ xs, ∀ y ∈ f x, (!p y) = true

theorem List.findIdx?_subtype.{u_1} {α : Type u_1} {p : α → Prop} {l : List { x // p x }}
  {f : { x // p x } → Bool} {g : α → Bool} (hf : ∀ (x : α) (h : p x), f ⟨x, h⟩ = g x) :
  List.findIdx? f l = List.findIdx? g l.unattach

theorem List.findIdx?_cons.{u_1} {α✝ : Type u_1} {x : α✝} {xs : List α✝} {p : α✝ → Bool} :
  List.findIdx? p (x :: xs) =
    if p x = true then some 0 else Option.map (fun i => i + 1) (List.findIdx? p xs)

theorem List.find?_flatMap.{u_1, u_2} {α : Type u_1} {β : Type u_2} {xs : List α} {f : α → List β}
  {p : β → Bool} :
  List.find? p (List.flatMap f xs) = List.findSome? (fun x => List.find? p (f x)) xs

theorem List.idxOf?_cons.{u_1} {α : Type u_1} [BEq α] {a : α} {xs : List α} {b : α} :
  List.idxOf? b (a :: xs) =
    if (a == b) = true then some 0 else Option.map (fun x => x + 1) (List.idxOf? b xs)

theorem List.findFinIdx?_cons.{u_1} {α : Type u_1} {p : α → Bool} {x : α} {xs : List α} :
  List.findFinIdx? p (x :: xs) =
    if p x = true then some 0 else Option.map Fin.succ (List.findFinIdx? p xs)

theorem List.lookup_eq_findSome?.{u_1, u_2} {α : Type u_2} [BEq α] {β : Type u_1} {l : List (α × β)}
  {k : α} :
  List.lookup k l = List.findSome? (fun p => if (k == p.1) = true then some p.2 else none) l

theorem List.find?_filterMap.{u_1, u_2} {α : Type u_1} {β : Type u_2} {xs : List α} {f : α → Option β}
  {p : β → Bool} :
  List.find? p (List.filterMap f xs) = (List.find? (fun a => Option.any p (f a)) xs).bind f

def Option.pmap_or.match_1.splitter✝.{u_1, u_2} {α : Type u_1} {p : α → Prop} {o' : Option α}
  (motive : (o : Option α) → {h : ∀ (a : α), o.or o' = some a → p a} → Sort u_2) (o✝ : Option α)
