theorem List.findIdx_subtype.{u_1} {α : Type u_1} {p : α → Prop} {l : List { x // p x }}
  {f : { x // p x } → Bool} {g : α → Bool} (hf : ∀ (x : α) (h : p x), f ⟨x, h⟩ = g x) :
  List.findIdx f l = List.findIdx g l.unattach

theorem List.getLast_filterMap.{u_1, u_2} {α : Type u_1} {β : Type u_2} {f : α → Option β} {l : List α}
  (h : List.filterMap f l ≠ []) :
  (List.filterMap f l).getLast h = (List.findSome? f l.reverse).get ⋯

theorem List.findFinIdx?_subtype.{u_1} {α : Type u_1} {p : α → Prop} {l : List { x // p x }}
  {f : { x // p x } → Bool} {g : α → Bool} (hf : ∀ (x : α) (h : p x), f ⟨x, h⟩ = g x) :
  List.findFinIdx? f l = Option.map (fun i => Fin.cast ⋯ i) (List.findFinIdx? g l.unattach)

theorem List.get_find?_replicate.{u_1} {α : Type u_1} {n : ℕ} {a : α} {p : α → Bool}
  (h : (List.find? p (List.replicate n a)).isSome = true) :
  (List.find? p (List.replicate n a)).get h = a

theorem List.findSome?_eq_some_iff.{u_1, u_2} {α : Type u_1} {β : Type u_2} {f : α → Option β} {l : List α}
  {b : β} :
  List.findSome? f l = some b ↔ ∃ l₁ a l₂, l = l₁ ++ a :: l₂ ∧ f a = some b ∧ ∀ x ∈ l₁, f x = none

theorem List.finIdxOf?_cons.{u_1} {α : Type u_1} {b : α} [BEq α] {a : α} {xs : List α} :
  List.finIdxOf? b (a :: xs) =
    if (a == b) = true then some ⟨0, ⋯⟩ else Option.map (fun x => x.succ) (List.finIdxOf? b xs)

theorem List.findSome?_replicate_of_isSome.{u_1, u_2} {α✝ : Type u_1} {α✝¹ : Type u_2} {f : α✝ → Option α✝¹}
  {n : ℕ} {a : α✝} :
  (f a).isSome = true → List.findSome? f (List.replicate n a) = if n = 0 then none else f a

theorem List.reverse_zipWith.{u_1, u_2, u_3} {α✝ : Type u_1} {α✝¹ : Type u_2} {α✝² : Type u_3}
  {f : α✝ → α✝¹ → α✝²} {l : List α✝} {l' : List α✝¹} (h : l.length = l'.length) :
  (List.zipWith f l l').reverse = List.zipWith f l.reverse l'.reverse

theorem List.lt_length_right_of_zipWith.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3}
  {f : α → β → γ} {i : ℕ} {l : List α} {l' : List β} (h : i < (List.zipWith f l l').length) :
  i < l'.length

theorem List.getElem_zipWith.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {f : α → β → γ}
  {l : List α} {l' : List β} {i : ℕ} {h : i < (List.zipWith f l l').length} :
  (List.zipWith f l l')[i] = f l[i] l'[i]

theorem List.zipWith_replicate.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {α✝ : Type u_3}
  {f : α → β → α✝} {a : α} {b : β} {m n : ℕ} :
  List.zipWith f (List.replicate m a) (List.replicate n b) = List.replicate (min m n) (f a b)
